// Browser entry point for the plain-DOM HAA demo.
import { createAudio } from '../src/runtime/createAudio.ts'
import type { AudioControls, BedHandle, HaaAudio } from '../src/contract.ts'
import type { DemoAction, DemoPanel } from './panel.ts'
import { installGpuOps, markReady } from './gpuOps.ts'
// @ts-ignore generated by scripts/build-demo.ts
import PANELS from '../out/demo-src/panels.gen.ts'

const panels = (PANELS as readonly DemoPanel[]).slice().sort((a, b) => a.order - b.order || a.id.localeCompare(b.id))
const canvas = document.querySelector<HTMLCanvasElement>('#meter')!
const root = document.querySelector<HTMLElement>('#panels')!
const status = document.querySelector<HTMLElement>('#error')!
const ctx2d = canvas.getContext('2d')!
const startButton = document.querySelector<HTMLButtonElement>('#start')!
let audio: HaaAudio | null = null
let starting: Promise<HaaAudio> | null = null
let lastLabel = 'Ready'

function start(): Promise<HaaAudio> {
  if (!starting) {
    const context = new AudioContext()
    starting = createAudio(context, { manifestUrl: './audio/manifest.json', processorUrl: './haa-processors.js' })
      .then((value) => { audio = value; status.textContent = ''; return value })
      .catch((error: unknown) => {
        const message = error instanceof Error ? error.message : String(error)
        status.textContent = message.startsWith('[haa]') ? message : `[haa] ${message}`
        throw error
      })
  }
  return starting
}

// Panels mount before Start, so this proxy starts audio on the first control use and forwards calls.
// Its immediate handles are deferred; the demo action buttons do not need synchronous return values.
const deferredAudio = new Proxy({} as AudioControls, {
  get(_target, key) {
    if (key === 'startBed') return (id: string, options?: Parameters<AudioControls['startBed']>[1]): BedHandle => {
      let bed: BedHandle | null = null
      const queued: ((target: BedHandle) => void)[] = []
      void start().then((a) => {
        bed = a.startBed(id, options)
        if (bed) for (const call of queued.splice(0)) call(bed)
      }).catch(() => {})
      const call = (fn: (target: BedHandle) => void) => { if (bed) fn(bed); else queued.push(fn) }
      return {
        get id() { return bed?.id ?? id },
        set: (values) => call((target) => target.set(values)),
        setParam: (name, value) => call((target) => target.setParam(name, value)),
        setPos: (pos, vel) => call((target) => target.setPos(pos, vel)),
        stop: (fadeSec) => call((target) => target.stop(fadeSec)),
      }
    }
    if (key === 'music') return new Proxy({}, {
      get(_music, method) { return (...args: unknown[]) => { void start().then((a) => (a.music as unknown as Record<PropertyKey, (...v: unknown[]) => unknown>)[method]!(...args)).catch(() => {}) } },
    })
    return (...args: unknown[]) => { void start().then((a) => (a as unknown as Record<PropertyKey, (...v: unknown[]) => unknown>)[key]!(...args)).catch(() => {}); return null }
  },
})

const actions: DemoAction[] = []
for (const panel of panels) {
  actions.push(...panel.actions())
  const section = document.createElement('section')
  const heading = document.createElement('h2')
  heading.textContent = panel.title
  section.append(heading)
  const controls = document.createElement('div')
  section.append(controls)
  controls.addEventListener('click', (event) => {
    const button = (event.target as HTMLElement).closest('button')
    if (button) lastLabel = button.textContent ?? panel.title
  })
  panel.mount(controls, deferredAudio)
  root.append(section)
}
startButton.addEventListener('click', () => { void start().catch(() => {}) })
installGpuOps(() => ({ audio, start, actions, canvas, drawMeter }))
markReady()

function db(value: number): number { return value > 0 ? Math.max(-100, 20 * Math.log10(value)) : -100 }
const meterBuffers = [0, 1, 2].map(() => new Float32Array(2048))
let levelsIndex = 0
/** Draws one opaque meter frame, also used synchronously by the GPU snapshot operation. */
function drawMeter(): void {
  levelsIndex = 0
  ctx2d.fillStyle = '#111827'
  ctx2d.fillRect(0, 0, canvas.width, canvas.height)
  ctx2d.fillStyle = '#e5e7eb'; ctx2d.font = '18px system-ui'
  const meters = audio?.meters
  const levels = meters ? [meters.mix, meters.left, meters.right].map((analyser) => {
    const samples = meterBuffers[levelsIndex++]!
    analyser.getFloatTimeDomainData(samples)
    let sum = 0
    for (const sample of samples) sum += sample * sample
    return db(Math.sqrt(sum / samples.length))
  }) : [-100, -100, -100]
  ctx2d.fillText(`Mix ${levels[0]!.toFixed(1)} dBFS`, 24, 34)
  ctx2d.fillText(`L ${levels[1]!.toFixed(1)} dBFS`, 24, 104)
  ctx2d.fillText(`R ${levels[2]!.toFixed(1)} dBFS`, 24, 174)
  const bar = (y: number, value: number, color: string) => {
    ctx2d.fillStyle = '#263244'; ctx2d.fillRect(220, y - 20, 700, 28)
    ctx2d.fillStyle = color; ctx2d.fillRect(220, y - 20, 700 * Math.max(0, Math.min(1, (value + 60) / 60)), 28)
  }
  bar(34, levels[0]!, '#38bdf8'); bar(104, levels[1]!, '#34d399'); bar(174, levels[2]!, '#fbbf24')
  ctx2d.fillStyle = '#e5e7eb'
  ctx2d.fillText(`${lastLabel} · ${levels[0]!.toFixed(1)} dBFS · ${audio?.ctx.state ?? 'not started'}`, 24, 222)
}
function draw(): void {
  drawMeter()
  requestAnimationFrame(draw)
}
requestAnimationFrame(draw)
